import { useState, useEffect, useCallback } from "react";
import { creneauApi, disponibiliteApi } from "../api/api";

const JOURS = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi"];

const SALLES = ["Salle A1", "Salle A2", "Salle B1", "Amphithéâtre"];

function StatCard({ label, value, color }) {
  return (
    <div style={{
      background: "var(--surface)", border: "1px solid var(--border)",
      borderRadius: "var(--radius)", padding: "20px 24px",
    }}>
      <div style={{ fontSize: 28, fontWeight: 600, color: color || "var(--text)", letterSpacing: "-0.5px" }}>
        {value}
      </div>
      <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4, textTransform: "uppercase", letterSpacing: "0.06em" }}>
        {label}
      </div>
    </div>
  );
}

function SectionTitle({ children }) {
  return (
    <div style={{
      fontSize: 11, color: "var(--muted)", textTransform: "uppercase",
      letterSpacing: "0.08em", marginBottom: 12, marginTop: 28,
    }}>
      {children}
    </div>
  );
}

function Input({ label, ...props }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
      {label && (
        <label style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em" }}>
          {label}
        </label>
      )}
      <input
        {...props}
        style={{
          padding: "8px 12px", borderRadius: 8,
          border: "1px solid var(--border2)", background: "var(--surface2)",
          color: "var(--text)", outline: "none", fontSize: 13,
          width: "100%",
          ...props.style,
        }}
      />
    </div>
  );
}

function Select({ label, children, ...props }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
      {label && (
        <label style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em" }}>
          {label}
        </label>
      )}
      <select
        {...props}
        style={{
          padding: "8px 12px", borderRadius: 8,
          border: "1px solid var(--border2)", background: "var(--surface2)",
          color: "var(--text)", outline: "none", fontSize: 13,
          width: "100%",
        }}
      >
        {children}
      </select>
    </div>
  );
}

function CreneauCard({ creneau }) {
  const isOccupe = creneau.statut === "OCCUPE";
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "14px 18px",
      background: "var(--surface)", border: "1px solid var(--border)",
      borderRadius: "var(--radius)", marginBottom: 8,
      borderLeft: `3px solid ${isOccupe ? "var(--amber)" : "var(--green)"}`,
    }}>
      <div>
        <div style={{ fontSize: 13, fontWeight: 500, color: "var(--text)", marginBottom: 3 }}>
          {creneau.salle}
        </div>
        <div style={{ fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
          {creneau.date} · {creneau.heureDebut} — {creneau.heureFin}
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <div style={{ fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
          {creneau.dureeMinutes} min
        </div>
        <span style={{
          fontSize: 11, fontWeight: 500, padding: "3px 10px", borderRadius: 20,
          background: isOccupe ? "rgba(245,158,11,0.12)" : "rgba(16,185,129,0.12)",
          color: isOccupe ? "var(--amber)" : "var(--green)",
        }}>
          {isOccupe ? "Occupé" : "Disponible"}
        </span>
      </div>
    </div>
  );
}

export default function Disponibilites() {
  const [creneaux, setCreneaux]         = useState([]);
  const [loading, setLoading]           = useState(true);
  const [error, setError]               = useState(null);
  const [success, setSuccess]           = useState(null);
  const [activeTab, setActiveTab]       = useState("creneaux");
  const [actionLoading, setActionLoading] = useState(false);

  // Form créneau
  const [formCreneau, setFormCreneau] = useState({
    date: "", heureDebut: "", dureeMinutes: "30", salle: "Salle A1",
  });

  // Form disponibilité
  const [formDispo, setFormDispo] = useState({
    professeurId: "", date: "", heureDebut: "", heureFin: "", disponible: true,
  });

  // Filter créneaux
  const [filterSalle, setFilterSalle]   = useState("TOUT");
  const [filterStatut, setFilterStatut] = useState("TOUT");

  const loadCreneaux = useCallback(async () => {
    setLoading(true);
    try {
      const data = await creneauApi.getDisponibles();
      setCreneaux(data);
      setError(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadCreneaux(); }, [loadCreneaux]);

  const showSuccess = (msg) => {
    setSuccess(msg);
    setTimeout(() => setSuccess(null), 3000);
  };

  const handleCreerCreneau = async (e) => {
    e.preventDefault();
    if (!formCreneau.date || !formCreneau.heureDebut) {
      setError("Date et heure de début sont obligatoires.");
      return;
    }
    setActionLoading(true);
    try {
      await creneauApi.creer({
        date: formCreneau.date,
        heureDebut: formCreneau.heureDebut + ":00",
        dureeMinutes: parseInt(formCreneau.dureeMinutes),
        salle: formCreneau.salle,
      });
      setFormCreneau({ date: "", heureDebut: "", dureeMinutes: "30", salle: "Salle A1" });
      showSuccess("Créneau créé avec succès.");
      await loadCreneaux();
    } catch (e) {
      setError(e.message);
    } finally {
      setActionLoading(false);
    }
  };

  const handleEnregistrerDispo = async (e) => {
    e.preventDefault();
    if (!formDispo.professeurId || !formDispo.date || !formDispo.heureDebut || !formDispo.heureFin) {
      setError("Tous les champs sont obligatoires.");
      return;
    }
    setActionLoading(true);
    try {
      await disponibiliteApi.enregistrer({
        professeur: { id: parseInt(formDispo.professeurId) },
        date: formDispo.date,
        heureDebut: formDispo.heureDebut + ":00",
        heureFin: formDispo.heureFin + ":00",
        disponible: formDispo.disponible,
      });
      setFormDispo({ professeurId: "", date: "", heureDebut: "", heureFin: "", disponible: true });
      showSuccess("Disponibilité enregistrée.");
    } catch (e) {
      setError(e.message);
    } finally {
      setActionLoading(false);
    }
  };

  const filteredCreneaux = creneaux.filter(c => {
    const salleOk  = filterSalle  === "TOUT" || c.salle   === filterSalle;
    const statutOk = filterStatut === "TOUT" || c.statut  === filterStatut;
    return salleOk && statutOk;
  });

  const countDisponibles = creneaux.filter(c => c.statut === "DISPONIBLE").length;
  const countOccupes     = creneaux.filter(c => c.statut === "OCCUPE").length;

  return (
    <div style={{ animation: "fadeIn 0.3s ease" }}>
      <style>{`
        @keyframes fadeIn { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:translateY(0) } }
        .tab-btn { transition: all 0.15s; }
        .tab-btn:hover { color: var(--text) !important; }
        .btn-submit { transition: opacity 0.15s, transform 0.1s; }
        .btn-submit:hover { opacity: 0.85; }
        .btn-submit:active { transform: scale(0.97); }
        input[type="date"]::-webkit-calendar-picker-indicator,
        input[type="time"]::-webkit-calendar-picker-indicator { filter: invert(0.6); cursor: pointer; }
      `}</style>

      {/* Header */}
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 6 }}>
          Phase 2
        </div>
        <h1 style={{ fontSize: 24, fontWeight: 600, color: "var(--text)", letterSpacing: "-0.4px" }}>
          Disponibilités & Créneaux
        </h1>
      </div>

      {/* Stats */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12, marginBottom: 28 }}>
        <StatCard label="Total créneaux"  value={creneaux.length}    />
        <StatCard label="Disponibles"     value={countDisponibles}   color="var(--green)" />
        <StatCard label="Occupés"         value={countOccupes}       color="var(--amber)" />
      </div>

      {/* Tabs */}
      <div style={{ display: "flex", gap: 2, borderBottom: "1px solid var(--border)", marginBottom: 24 }}>
        {[
          { id: "creneaux",       label: "Créneaux de soutenance" },
          { id: "disponibilites", label: "Disponibilités des profs" },
        ].map(t => (
          <button key={t.id} className="tab-btn"
            onClick={() => setActiveTab(t.id)}
            style={{
              padding: "10px 18px", border: "none", background: "none", cursor: "pointer",
              fontSize: 13, fontWeight: activeTab === t.id ? 500 : 400,
              color: activeTab === t.id ? "var(--text)" : "var(--muted)",
              borderBottom: activeTab === t.id ? "2px solid var(--accent)" : "2px solid transparent",
              marginBottom: -1,
            }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* Alerts */}
      {error && (
        <div style={{
          background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.3)",
          color: "#ef4444", borderRadius: "var(--radius)", padding: "10px 14px",
          fontSize: 13, marginBottom: 16,
        }}>
          {error}
          <button onClick={() => setError(null)} style={{ float: "right", background: "none", border: "none", color: "#ef4444", cursor: "pointer" }}>
            x
          </button>
        </div>
      )}
      {success && (
        <div style={{
          background: "rgba(16,185,129,0.1)", border: "1px solid rgba(16,185,129,0.3)",
          color: "var(--green)", borderRadius: "var(--radius)", padding: "10px 14px",
          fontSize: 13, marginBottom: 16,
        }}>
          {success}
        </div>
      )}

      {/* ── TAB CRÉNEAUX ── */}
      {activeTab === "creneaux" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 340px", gap: 24, alignItems: "start" }}>

          {/* Liste */}
          <div>
            {/* Filtres */}
            <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
              <select
                value={filterSalle}
                onChange={e => setFilterSalle(e.target.value)}
                style={{
                  padding: "6px 12px", borderRadius: 8, border: "1px solid var(--border2)",
                  background: "var(--surface2)", color: "var(--text)", fontSize: 13, outline: "none",
                }}>
                <option value="TOUT">Toutes les salles</option>
                {SALLES.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <select
                value={filterStatut}
                onChange={e => setFilterStatut(e.target.value)}
                style={{
                  padding: "6px 12px", borderRadius: 8, border: "1px solid var(--border2)",
                  background: "var(--surface2)", color: "var(--text)", fontSize: 13, outline: "none",
                }}>
                <option value="TOUT">Tous les statuts</option>
                <option value="DISPONIBLE">Disponible</option>
                <option value="OCCUPE">Occupé</option>
              </select>
            </div>

            {loading && (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {[1,2,3].map(i => (
                  <div key={i} style={{
                    height: 64, borderRadius: "var(--radius)",
                    background: "var(--surface)", border: "1px solid var(--border)",
                    opacity: 1 - i * 0.2,
                  }} />
                ))}
              </div>
            )}

            {!loading && filteredCreneaux.length === 0 && (
              <div style={{ textAlign: "center", padding: "48px 0", color: "var(--muted)" }}>
                Aucun créneau trouvé.
              </div>
            )}

            {filteredCreneaux.map(c => <CreneauCard key={c.id} creneau={c} />)}
          </div>

          {/* Formulaire créer créneau */}
          <div style={{
            background: "var(--surface)", border: "1px solid var(--border)",
            borderRadius: "var(--radius-lg)", padding: "20px",
            position: "sticky", top: 24,
          }}>
            <div style={{ fontSize: 13, fontWeight: 500, color: "var(--text)", marginBottom: 16 }}>
              Nouveau créneau
            </div>

            <form onSubmit={handleCreerCreneau} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <Input
                label="Date"
                type="date"
                value={formCreneau.date}
                onChange={e => setFormCreneau(p => ({ ...p, date: e.target.value }))}
              />
              <Input
                label="Heure de début"
                type="time"
                value={formCreneau.heureDebut}
                onChange={e => setFormCreneau(p => ({ ...p, heureDebut: e.target.value }))}
              />
              <Select
                label="Durée"
                value={formCreneau.dureeMinutes}
                onChange={e => setFormCreneau(p => ({ ...p, dureeMinutes: e.target.value }))}
              >
                <option value="20">20 minutes</option>
                <option value="30">30 minutes</option>
                <option value="45">45 minutes</option>
                <option value="60">60 minutes</option>
              </Select>
              <Select
                label="Salle"
                value={formCreneau.salle}
                onChange={e => setFormCreneau(p => ({ ...p, salle: e.target.value }))}
              >
                {SALLES.map(s => <option key={s} value={s}>{s}</option>)}
              </Select>

              <button type="submit" className="btn-submit"
                disabled={actionLoading}
                style={{
                  marginTop: 4, padding: "9px 0", borderRadius: 8,
                  border: "none", background: "var(--accent)", color: "#fff",
                  fontSize: 13, fontWeight: 500,
                  opacity: actionLoading ? 0.6 : 1,
                }}>
                {actionLoading ? "Création..." : "Créer le créneau"}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* ── TAB DISPONIBILITÉS ── */}
      {activeTab === "disponibilites" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 340px", gap: 24, alignItems: "start" }}>

          {/* Calendrier visuel des dispos */}
          <div>
            <SectionTitle>Aperçu hebdomadaire</SectionTitle>
            <div style={{
              background: "var(--surface)", border: "1px solid var(--border)",
              borderRadius: "var(--radius-lg)", overflow: "hidden",
            }}>
              {/* Header jours */}
              <div style={{
                display: "grid", gridTemplateColumns: "80px repeat(5, 1fr)",
                borderBottom: "1px solid var(--border)",
              }}>
                <div style={{ padding: "10px 14px" }} />
                {JOURS.map(j => (
                  <div key={j} style={{
                    padding: "10px 0", textAlign: "center",
                    fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em",
                    borderLeft: "1px solid var(--border)",
                  }}>
                    {j}
                  </div>
                ))}
              </div>

              {/* Lignes horaires */}
              {["08:00","09:00","10:00","11:00","14:00","15:00","16:00"].map(h => (
                <div key={h} style={{
                  display: "grid", gridTemplateColumns: "80px repeat(5, 1fr)",
                  borderBottom: "1px solid var(--border)",
                }}>
                  <div style={{
                    padding: "10px 14px", fontSize: 11,
                    color: "var(--muted)", fontFamily: "'DM Mono', monospace",
                  }}>
                    {h}
                  </div>
                  {JOURS.map((_, i) => (
                    <div key={i} style={{
                      borderLeft: "1px solid var(--border)",
                      height: 36,
                      background: Math.random() > 0.6 ? "rgba(16,185,129,0.06)" : "transparent",
                    }} />
                  ))}
                </div>
              ))}
            </div>
            <div style={{ display: "flex", gap: 16, marginTop: 10 }}>
              {[
                { color: "rgba(16,185,129,0.2)", label: "Disponible" },
                { color: "transparent",          label: "Non renseigné" },
              ].map(l => (
                <div key={l.label} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: "var(--muted)" }}>
                  <span style={{ width: 12, height: 12, borderRadius: 3, background: l.color, border: "1px solid var(--border)", display: "inline-block" }} />
                  {l.label}
                </div>
              ))}
            </div>
          </div>

          {/* Formulaire disponibilité */}
          <div style={{
            background: "var(--surface)", border: "1px solid var(--border)",
            borderRadius: "var(--radius-lg)", padding: "20px",
            position: "sticky", top: 24,
          }}>
            <div style={{ fontSize: 13, fontWeight: 500, color: "var(--text)", marginBottom: 16 }}>
              Enregistrer une disponibilité
            </div>

            <form onSubmit={handleEnregistrerDispo} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              <Input
                label="ID Professeur"
                type="number"
                placeholder="ex: 2"
                value={formDispo.professeurId}
                onChange={e => setFormDispo(p => ({ ...p, professeurId: e.target.value }))}
              />
              <Input
                label="Date"
                type="date"
                value={formDispo.date}
                onChange={e => setFormDispo(p => ({ ...p, date: e.target.value }))}
              />
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
                <Input
                  label="De"
                  type="time"
                  value={formDispo.heureDebut}
                  onChange={e => setFormDispo(p => ({ ...p, heureDebut: e.target.value }))}
                />
                <Input
                  label="À"
                  type="time"
                  value={formDispo.heureFin}
                  onChange={e => setFormDispo(p => ({ ...p, heureFin: e.target.value }))}
                />
              </div>

              <Select
                label="Statut"
                value={formDispo.disponible}
                onChange={e => setFormDispo(p => ({ ...p, disponible: e.target.value === "true" }))}
              >
                <option value="true">Disponible</option>
                <option value="false">Indisponible</option>
              </Select>

              <button type="submit" className="btn-submit"
                disabled={actionLoading}
                style={{
                  marginTop: 4, padding: "9px 0", borderRadius: 8,
                  border: "none", background: "var(--accent)", color: "#fff",
                  fontSize: 13, fontWeight: 500,
                  opacity: actionLoading ? 0.6 : 1,
                }}>
                {actionLoading ? "Enregistrement..." : "Enregistrer"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
